package org.apache.commons.codec.binary;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

public class BinaryCodecTest_testToAsciiChars {

    private static final int BIT_0 = 0x01;
    private static final int BIT_1 = 0x02;
    private static final int BIT_2 = 0x04;
    private static final int BIT_3 = 0x08;
    private static final int BIT_4 = 0x10;
    private static final int BIT_5 = 0x20;
    private static final int BIT_6 = 0x40;
    private static final int BIT_7 = 0x80;

    private static final byte ALL_BITS = (byte) (BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6 | BIT_7);

    @Test
    void testToAsciiChars() {
        assertAsciiChars("00000000", new byte[1]);
        assertAsciiChars("00000001", oneByte(BIT_0));
        assertAsciiChars("00000011", oneByte(BIT_0 | BIT_1));
        assertAsciiChars("00000111", oneByte(BIT_0 | BIT_1 | BIT_2));
        assertAsciiChars("00001111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3));
        assertAsciiChars("00011111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4));
        assertAsciiChars("00111111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5));
        assertAsciiChars("01111111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6));
        assertAsciiChars("11111111", oneByte(ALL_BITS));

        assertAsciiChars("0000000000000000", new byte[2]);
        assertAsciiChars("0000000000000001", twoBytes(BIT_0, 0));
        assertAsciiChars("0000000000000011", twoBytes(BIT_0 | BIT_1, 0));
        assertAsciiChars("0000000000000111", twoBytes(BIT_0 | BIT_1 | BIT_2, 0));
        assertAsciiChars("0000000000001111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3, 0));
        assertAsciiChars("0000000000011111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4, 0));
        assertAsciiChars("0000000000111111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5, 0));
        assertAsciiChars("0000000001111111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6, 0));
        assertAsciiChars("0000000011111111", twoBytes(ALL_BITS, 0));

        assertAsciiChars("0000000111111111", twoBytes(ALL_BITS, BIT_0));
        assertAsciiChars("0000001111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1));
        assertAsciiChars("0000011111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2));
        assertAsciiChars("0000111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3));
        assertAsciiChars("0001111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4));
        assertAsciiChars("0011111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5));
        assertAsciiChars("0111111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6));
        assertAsciiChars("1111111111111111", twoBytes(ALL_BITS, ALL_BITS));

        assertEquals(0, BinaryCodec.toAsciiChars((byte[]) null).length);
    }

    private static void assertAsciiChars(final String expected, final byte[] bits) {
        assertEquals(expected, new String(BinaryCodec.toAsciiChars(bits)));
    }

    private static byte[] oneByte(final int value) {
        return new byte[] { (byte) value };
    }

    private static byte[] twoBytes(final int firstByte, final int secondByte) {
        return new byte[] { (byte) firstByte, (byte) secondByte };
    }
}
